### S1: Implement a safe configuration management system.

```python
import copy
from typing import Any, Dict

class ConfigManager:
    """
    Safe configuration management.
    - Immutable defaults
    - Environment-specific overrides
    - No cross-contamination between environments
    """

    _DEFAULTS: Dict[str, Any] = {
        "database": {
            "host":     "localhost",
            "port":     5432,
            "pool_size": 5,
            "options":  ["ssl", "timeout=30"],
        },
        "cache": {
            "backend":  "redis",
            "hosts":    ["localhost:6379"],
            "ttl":      3600,
        },
        "features": ["logging", "metrics"],
        "limits":   {"rate": 100, "burst": 200, "daily": 10000},
    }

    def __init__(self):
        self._environments: Dict[str, dict] = {}

    def create_environment(self, name: str, overrides: dict = None) -> dict:
        """Create environment config with deep copy of defaults"""
        config = copy.deepcopy(self._DEFAULTS)   # Deep copy defaults!

        if overrides:
            self._deep_merge(config, overrides)

        self._environments[name] = config
        return config

    def _deep_merge(self, base: dict, override: dict) -> None:
        """Recursively merge override into base"""
        for key, value in override.items():
            if key in base and isinstance(base[key], dict) and isinstance(value, dict):
                self._deep_merge(base[key], value)
            elif key in base and isinstance(base[key], list) and isinstance(value, list):
                base[key] = value   # Replace list (don't extend)
            else:
                base[key] = copy.deepcopy(value)

    def get_config(self, environment: str) -> dict:
        """Returns a copy so caller can't mutate stored config"""
        config = self._environments.get(environment)
        if not config:
            raise KeyError(f"Environment '{environment}' not found")
        return copy.deepcopy(config)   # Return copy!

    def update_config(self, environment: str, updates: dict) -> None:
        """Update specific config values"""
        config = self._environments.get(environment)
        if config:
            self._deep_merge(config, copy.deepcopy(updates))

mgr = ConfigManager()

# Create environments
dev  = mgr.create_environment("dev")
prod = mgr.create_environment("prod", {
    "database": {"host": "prod-db.internal", "pool_size": 20},
    "cache":    {"hosts": ["cache1:6379", "cache2:6379"]},
    "limits":   {"rate": 1000, "burst": 2000},
})
staging = mgr.create_environment("staging", {
    "database": {"host": "staging-db.internal"},
})

# Mutating a retrieved config should NOT affect stored config
dev_config = mgr.get_config("dev")
dev_config["database"]["host"] = "HACKED"   # Try to corrupt!

# Original is safe
fresh_dev = mgr.get_config("dev")
print(f"Dev host (safe): {fresh_dev['database']['host']}")   # "localhost"
print(f"Prod host:       {mgr.get_config('prod')['database']['host']}")  # "prod-db.internal"
print(f"Staging host:    {mgr.get_config('staging')['database']['host']}")  # "staging-db.internal"

# Environments don't share nested objects
prod_config    = mgr.get_config("prod")
staging_config = mgr.get_config("staging")
same_features  = prod_config["features"] is staging_config["features"]
print(f"Features lists shared: {same_features}")  # False — independent!
```
